item.command:
/bin/zsh -lc 'set -e
q=.qfactory/tools/node_modules/.bin/qloop
orig=.qf/originals/webhook-relay-1.0.0.yaml
adapt=loops/webhook-relay-local-probe.yaml
before_orig=$(shasum -a 256 "$orig" | awk '"'{print "'$1}'"')
before_adapt="'$(shasum -a 256 "$adapt" | awk '"'{print "'$1}'"')
QF_NO_UPDATE_CHECK=1 \""'$q" run "$adapt"
after_orig=$(shasum -a 256 "$orig" | awk '"'{print "'$1}'"')
after_adapt="'$(shasum -a 256 "$adapt" | awk '"'{print "'$1}'"')
if [ \""'$before_orig" != "$after_orig" ] || [ "$before_adapt" != "$after_adapt" ]; then
  echo '"'manifest hash changed' >&2; exit 1
fi
run="'$(find loops/.qf/runs -type f -name '"'*.json' -print | sort | tail -1)
printf '%s\\n' '--- manifest hash comparison ---'
printf 'original before=%s after=%s unchanged=%s\\n' \""'$before_orig" "$after_orig" yes
printf '"'adapted  before=%s after=%s unchanged=%s\\n' \""'$before_adapt" "$after_adapt" yes
printf '"'%s\\n' '--- new run evidence ---'
sed -n '1,260p' \""'$run"
printf '"'%s\\n' '--- independent repeat check ---'
node - \""'$run" <<'"'NODE'
const fs=require('fs');
const file=process.argv[2], run=JSON.parse(fs.readFileSync(file,'utf8'));
const expected={project:'synthetic-qf',items:[1,2,3],total:6};
const step=run.steps.find(s=>s.stepId==='wr-fetch');
if(run.status"'!=='"'success') throw new Error('run not successful');
if(JSON.stringify(step.output.json)"'!==JSON.stringify(expected)) throw new Error('"'actual output mismatch');
if(step.config.url"'!=='"'http://127.0.0.1:58415/data') throw new Error('source changed');
if(run.steps.some(s=>s.kind==='api-request')) throw new Error('outbound step found');
console.log(JSON.stringify({runId:run.runId,status:run.status,actual:step.output.json,independentCheck:'PASS',outboundSteps:0},null,2));
NODE"

